package com.shiphappens.logistics.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="delivery_assignments") public class DeliveryAssignment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="shipment_id") private Shipment shipment; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="driver_id") private Driver driver; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="vehicle_id") private Vehicle vehicle; @Enumerated(EnumType.STRING) private Statuses.DeliveryStatus status=Statuses.DeliveryStatus.ASSIGNED; @Column(name="assigned_at") private Instant assignedAt; @Column(name="pickup_at") private Instant pickupAt; @Column(name="out_for_delivery_at") private Instant outForDeliveryAt; @Column(name="delivered_at") private Instant deliveredAt; @Column(name="failure_reason") private String failureReason; @PrePersist void created(){assignedAt=Instant.now();} public Long getId(){return id;} public Shipment getShipment(){return shipment;} public void setShipment(Shipment v){shipment=v;} public Driver getDriver(){return driver;} public void setDriver(Driver v){driver=v;} public Vehicle getVehicle(){return vehicle;} public void setVehicle(Vehicle v){vehicle=v;} public Statuses.DeliveryStatus getStatus(){return status;} public void setStatus(Statuses.DeliveryStatus v){status=v;} public void setPickupAt(Instant v){pickupAt=v;} public void setOutForDeliveryAt(Instant v){outForDeliveryAt=v;} public void setDeliveredAt(Instant v){deliveredAt=v;} public void setFailureReason(String v){failureReason=v;} }
